const filters = { status, range };        // new identity every render

// Variant A — synchronous
useEffect(() => {
  setRows(applyFilters(data, filters));   // applyFilters returns a new array
}, [data, filters]);

// Variant B — async
useEffect(() => {
  fetchAndFilter(data, filters)
